/**
 * @file dev-source.tsx
 * @description The developer docs' Fumadocs source: a second loader, built
 * from the `devDocs` collection (`dev-docs/`), with its own page tree, search
 * index and URLs under `/docs/dev`.
 *
 * It shares nothing with `source` (./source.tsx) but the MDX compiler, so a
 * developer page never shows up in the user docs' sidebar, search, sitemap,
 * llms.txt or the app sidebar's Docs tree, all of which read `source`.
 */
// Generated by fumadocs-mdx from ../../source.config.ts.
import { devDocs } from '../../.source/server'
import { type InferPageType, loader } from 'fumadocs-core/source'
import { lucideIconsPlugin } from 'fumadocs-core/source/lucide-icons'
import { DEV_DOCS_BASE_PATH, withDevBasePath } from './base-path'

export const devSource = loader({
  baseUrl: DEV_DOCS_BASE_PATH,
  plugins: [lucideIconsPlugin()],
  source: devDocs.toFumadocsSource(),
})

export type DevPage = InferPageType<typeof devSource>

/**
 * Origin-absolute URL of a developer page's processed Markdown, served by
 * `routes/dev-llms-mdx-route.ts` (mounted at `/docs/dev/llms.mdx/…`).
 */
export function devPageMarkdownUrl(page: DevPage): string {
  const slugs = page.slugs.length > 0 ? page.slugs : ['index']
  return withDevBasePath(`/llms.mdx/${slugs.join('/')}.mdx`)
}

export async function getDevLLMText(page: DevPage) {
  return `# ${page.data.title} (${page.url})

${await page.data.getText('processed')}`
}
